from Crypto.Cipher import AES
KEY = bytes.fromhex('0f1e2d3c4b5a69788796a5b4c3d2e1f0')
IV = bytes.fromhex('000102030405060708090a0b0c0d0e0f')
def dec_block(ct):
    return AES.new(KEY, AES.MODE_CBC, IV).decrypt(ct)
def valid_pad(pt):
    p = pt[-1]
    return 1 <= p <= 16 and pt[-p:] == bytes([p])*p
ct = open('cipher.bin','rb').read()
blocks = [ct[i:i+16] for i in range(0, len(ct), 16)]
out = b''
prev = IV
for blk in blocks:
    inter = bytearray(16)
    for pad in range(1, 17):
        for g in range(256):
            forged = bytearray(prev)
            forged[-pad] = g
            for k in range(1, pad):
                forged[-k] = inter[-k] ^ pad
            pt = dec_block(bytes(forged) + blk)
            if valid_pad(pt):
                if pad == 1:
                    f2 = bytearray(forged); f2[-2] ^= 0x01
                    if not valid_pad(dec_block(bytes(f2) + blk)):
                        continue
                inter[-pad] = g ^ pad
                break
    out += bytes(a ^ b for a, b in zip(inter, prev))
    prev = blk
print(out.decode('latin-1'))
